UPDATE companies SET description='Texas Mesquite Co. operates from a showroom and workshop in Bertram, Texas, about 45 miles northwest of Austin. The company was founded in 1989 by Craig Lagerstrom, who began building custom mesquite furniture that year and moved to the current location in 1999. Lagerstrom remains the sole owner and operator, and is a member of the Texas Mesquite Association.

The shop produces hand-crafted solid mesquite furniture for homes and offices, including dining tables, coffee tables, beds, nightstands, entertainment centers, case goods, and specialty items such as fireplace mantles and lamps. Each piece starts with mesquite lumber hand-selected at the sawmill; reclaimed antique wood from pre‑1940s structures is also incorporated. Traditional joinery and hand‑carving are used throughout, and select pieces feature turquoise inlay or walnut accents. The company does not disclose facility size, headcount, or annual volume.

Texas Mesquite Co. serves residential and commercial clients seeking custom western, rustic, or contemporary designs. Its work has been featured in national publications such as Cowboys & Indians, Texas Highways, and Veranda. Customers order directly through the Bertram showroom or via the company website for custom commissions.

The firm emphasizes heirloom‑quality construction meant to last generations, positioning its furniture as an investment rather than a disposable good. Lagerstrom’s personal involvement in every build and the use of hand‑picked, locally sourced mesquite are cited as key differentiators.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design", "Hand-carving", "Hand selection of mesquite lumber", "Turquoise inlay", "Reclaimed wood processing", "Old-world joinery techniques"], "industries": ["Residential furniture", "Office furniture", "Custom woodworking"], "materials": ["Texas mesquite", "Reclaimed antique wood (pre-1940s)", "Turquoise", "Walnut"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Hand-picked mesquite lumber at the sawmill", "Reclaimed antique wood from pre\u20111940s structures", "Hand-carving and old-world joinery on every piece", "Turquoise inlay and walnut accent options", "Featured in Cowboys & Indians, Texas Highways, Veranda"], "facts_used": ["Founded in 1989 by Craig Lagerstrom -> db", "Current location since 1999 -> /", "Owned and operated by Craig Lagerstrom -> /", "Member of Texas Mesquite Association -> /", "Featured in Cowboys & Indians, Texas Highways, Veranda -> /", "Hand-crafted custom mesquite furniture for home and office -> /", "Hand-picked mesquite at sawmill -> /", "Reclaimed antique wood from pre-1940s structures -> /", "Hand-carving and old-world craftsmanship -> /", "Turquoise inlay and walnut accents -> /", "Showroom in Bertram, Texas -> /", "Custom-build any piece, set, or suite -> /", "Headquarters: Bertram, Texas -> db", "Website: http://www.texmes.com/ -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "hand-crafted home and office furniture built from Texas Mesquite", "founded_year": "1989", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='texas-mesquite-co' AND approved AND profile IS NULL;
UPDATE companies SET description='Textiles Coated International (TCI) operates from Londonderry, New Hampshire, where it has manufactured high-performance fluoropolymer films, laminates, and composites since 1985. The company runs a 180,000-square-foot facility staffed by roughly 300 employees working around the clock.

TCI’s core processes include coating, lamination, fabrication, film casting, mixing, and in-house research and development supported by a dedicated laboratory. Its product line centers on proprietary all-PTFE CrossFilm™, alongside cast PTFE films, PFA, FEP, ETFE, PVDF, and ECTFE films, and PTFE-coated fiberglass fabrics. These materials are converted into ducting, belting, insulation covers, expansion-joint fabrics, and other components either by TCI or its customers.

The company serves architectural and greenhouse film producers, composite processors, removable-insulation-jacket fabricators, tank-liner and secondary-containment suppliers, radome-cover makers, floating-roof-seal manufacturers, and non-metallic expansion-joint builders. End markets include aerospace, chemical processing, electronics, energy, food processing, industrial, and medical/pharmaceutical sectors. TCI also supplied critical raw material for COVID-19 vaccine packaging under Operation Warp Speed.

TCI differentiates itself as the sole supplier offering the full range of PFA, FEP, ETFE, PVDF, ECTFE, cast PTFE, and 100% PTFE CrossFilm™. The CrossFilm™ barrier material provides unlimited shelf life, chemical and UV resistance, dynamic temperature stability, weatherability, and heat-sealability. The company holds multiple patents and awards, emphasizing long-term solutions, reliable supply, and custom engineering for applications where material failure is unacceptable.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Coating", "Lamination", "Fabrication", "Film casting", "Mixing", "Research and development", "Laboratory testing", "Expansion joint fabrication", "Composite molding", "Removable insulation jacketing", "Gas seal expansion joint service"], "industries": ["Architectural/Greenhouse films", "Composite process materials", "Removable insulation jacket materials", "Tank liners", "Secondary containment", "Radome covers", "Floating roof seal materials", "PTFE flexible ducting", "PTFE food belting", "Non-metallic expansion joint manufacturing", "Aerospace", "Chemical processing", "Electronics", "Energy", "Food processing", "Industrial", "Medical/Pharmaceutical"], "materials": ["PFA", "FEP", "ETFE", "PVDF", "ECTFE", "Cast PTFE films", "100% PTFE CrossFilm\u2122", "PTFE-coated fiberglass fabrics", "Fluoropolymer films", "Laminates", "Composites"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Only supplier offering PFA, FEP, ETFE, PVDF, ECTFE, cast PTFE films, and 100% PTFE CrossFilm\u2122", "Proprietary all-PTFE CrossFilm\u2122 with unlimited shelf life, chemical/UV/temperature resistance, and heat-sealability", "180,000 ft\u00b2 facility with 24/7 manufacturing and 300+ employees enabling short lead times", "Multiple patents and awards for innovative PTFE material development", "Custom engineering and fabrication for non-metallic expansion joints and challenging environments"], "facts_used": ["Founded 1985 -> /about", "Headquarters Londonderry, NH -> db", "300 employees -> /about and db", "180,000 ft\u00b2 manufacturing space -> /about", "24/7 manufacturing schedule -> /about", "Proprietary CrossFilm\u2122 material -> /about and /", "Materials: PFA, FEP, ETFE, PVDF, ECTFE, cast PTFE, CrossFilm\u2122 -> /", "Industries served: architectural, composite, insulation, tank liners, secondary containment, radome, floating roof, ducting, food belting, expansion joints -> /", "End markets: aerospace, chemical processing, electronics, energy, food processing, industrial, medical/pharmaceutical -> /about", "CAGE code 6SLV3 -> /about", "Duns# 11-834-0710 -> /about", "NAICS codes 313320, 541712, 326113, 326199, 326130, 314999 -> /about", "ISO certification mentioned -> /about", "Patents and awards -> /about", "Supplied COVID-19 vaccine packaging material -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Textiles Coated International (TCI) has been a leading manufacturer of high-performance fluoropolymer films, laminates, and composites since 1985.", "founded_year": "1985", "employee_count": "300", "cage_code": "6SLV3", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='textiles-coated-international' AND approved AND profile IS NULL;
UPDATE companies SET description='The company installs residential solar photovoltaic systems and whole-home backup power solutions, notably FranklinWH battery storage systems. It also provides ongoing service and repair for existing solar arrays, specializing in "orphaned" systems originally installed by defunct contractors such as Shine Solar, Sun Valley Renewables, and SunPro/ADT Solar. The firm coordinates no-money-down financing through multiple lenders and offers 24/7 production monitoring for installed systems.

That Solar Company serves homeowners in Missouri seeking to reduce grid reliance and lower electricity bills. Its customer base includes both new solar adopters and owners of legacy systems left without support when their original installers ceased operations. The company also works with referral partners who earn a $1,000 bonus when a referred project receives permission to operate.

The company distinguishes itself through a lifetime warranty valid for as long as the homeowner owns the property, a no-pressure sales process that provides custom estimates without a sales call, and a mission to educate customers on renewable energy options.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Residential solar PV system installation", "Whole-home battery backup system installation (FranklinWH)", "Solar system service and repair", "Orphaned solar system servicing", "Energy production monitoring", "Financing coordination", "Custom energy estimation (no sales call)"], "industries": ["Residential solar energy", "Home energy storage", "Solar system maintenance and repair"], "materials": [], "equipment": ["FranklinWH battery storage systems"], "volume": "", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded in 2005 by Bud Pierce in Springfield, Missouri -> db", "Offers lifetime warranty for as long as homeowner owns home -> /", "Provides 24/7 production monitoring -> /", "Installs FranklinWH whole home backup power systems -> /", "Offers no money down financing -> /", "Specializes in servicing orphaned solar systems (lists specific companies) -> /", "Provides custom estimates without sales call -> /", "Mission to educate customers and empower energy choice -> /about", "Referral program with $1,000 bonus -> /", "Headquarters Springfield, Missouri -> db"], "company_type": "Installer / service company", "makes_products": "no", "type_evidence": "At That Solar Company, we specialize in servicing orphaned solar systems \u2014 even if we didn''t install them.", "founded_year": "2005", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='that-solar-company-llc' AND approved AND profile IS NULL;
UPDATE companies SET description='The Advertising Specialists of Maine is based in Orono, a community in the Bangor metropolitan area of Maine. The business is woman-owned, though the exact founding year and the names of its founders are not disclosed in public sources.

