UPDATE companies SET description='The Sweet Life Kettle Corn Company operates from Farmington, Maine, where it was established in 1949 as a family-owned enterprise. The business was founded by Jodi Cordes on the premise of producing handcrafted gourmet popcorn while creating meaningful employment for local high school students. What began as a passion for kettle corn has evolved into a mission-driven operation that balances snack production with youth development.

The company produces four core kettle corn varieties—Blue Sky Blueberry, Tall Pines Pumpkin Spice, Coastal Cinnamon Crunch, and the original "ME Bag" Hand Popped Kettle Corn—in small batches using all-natural ingredients. Each 4.5- to 5.5-ounce bag is hand-popped with popcorn, pure cane sugar, oil, salt, and natural flavorings such as blueberries, vanilla, cinnamon, or pumpkin spice. The facility turns out gluten-free, dairy-free, non-GMO, and vegan-friendly snacks that ship within one to three business days.

Products reach consumers through the company''s e-commerce site, a growing network of Maine retailers, community events, and fundraising partnerships. The customer base spans individual snack buyers, gift purchasers, event organizers, and organizations seeking mission-aligned fundraising options. Every sale directly funds flexible work shifts for students who juggle academics, athletics, and extracurriculars.

Cordes started the venture to give teenagers real-world experience in customer service, teamwork, and entrepreneurship. The "purpose behind every bag" model means each purchase underwrites skill-building wages for young workers, tying the brand''s growth to community impact rather than scale alone.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Small-batch kettle corn cooking", "Hand popping", "Flavor formulation (blueberry, pumpkin spice, cinnamon)", "All-natural ingredient sourcing", "Gluten-free, dairy-free, non-GMO, vegan production", "Retail packaging (4.5-5.5 oz bags)", "Order fulfillment and shipping", "Fundraising program management", "Retail distribution"], "industries": ["Snack food manufacturing", "Gourmet specialty foods", "Gift and specialty retail", "Fundraising products", "Youth employment programs"], "materials": ["Popcorn", "Pure cane sugar", "Oil", "Salt", "Blueberries", "Vanilla extract", "Cinnamon", "Pumpkin spice blend"], "equipment": [], "volume": "", "lead_time": "1-3 business days for online orders", "tolerances": "", "built_on": ["Handcrafted small-batch production in Maine", "All-natural, gluten-free, dairy-free, non-GMO, vegan ingredients", "Employment program for local high school students", "1-3 business day shipping on online orders", "Sold through Maine retail network and direct-to-consumer"], "facts_used": ["Founded 1949 -> db", "Farmington, Maine location -> db", "Family-owned -> description (db)", "Founder Jodi Cordes -> /about-us", "Handcrafted small-batch kettle corn -> / and /about-us", "All-natural, gluten-free, dairy-free, non-GMO, vegan -> / and /about-us", "Employs local high school students -> / and /about-us", "Products: Blue Sky Blueberry, Tall Pines Pumpkin Spice, Coastal Cinnamon Crunch, ME Bag -> /", "Ships in 1-3 business days -> /", "Sold through local Maine retailers -> /", "Mission to support youth -> /about-us", "Ingredients listed -> /"], "company_type": "Manufacturer", "makes_products": "yes", "typ