ort_compliance": [], "languages": [], "social_links": ["https://www.linkedin.com/company/triad-plastic-technologies/"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='triad-plastic-technologies' AND approved AND profile IS NULL;
UPDATE companies SET description='Trickett Woodworks Co. was founded in 1975 in Auburn, New Hampshire, and remains a family-owned operation serving New England, New York, and beyond. The company’s products have been installed throughout the country.

The firm operates a 10,000-square-foot production shop where it performs all millwork and finishing in-house. Its capabilities span architectural millwork, custom cabinetry, custom woodwork, trim, moldings, built-in cabinetry, and finish carpentry, supported by estimating and project management services. The shop handles projects from concept to completion, ensuring precision and reliability for each client.

Trickett Woodworks works with general contractors, architects, designers, and property owners across commercial, residential, healthcare, hospitality, and corporate sectors. Project examples include a Boston professional office, a healthcare facility, a corporate café, a hotel pub, residential kitchens, and corporate reception areas.

The company emphasizes its ability to tackle challenging designs and deliver custom finishes on schedule, a reputation recognized by a 2022 Boston Society of Architects Award. General Manager Charlie Trickett oversees operations.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Architectural millwork", "Custom cabinetry", "Custom woodwork", "Trim", "Moldings", "Built-in cabinetry", "Finish carpentry", "Estimating", "Project management"], "industries": ["Commercial", "Residential", "Healthcare", "Hospitality", "Corporate"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["10,000-square-foot in-house production shop", "Tackles challenging designs with custom finishes delivered on time", "2022 Boston Society of Architects Award winner", "Family-owned with service across New England and New York", "In-house estimating and project management"], "facts_used": ["Founded 1975 in Auburn, NH -> db", "Family-owned -> db", "10,000 sq ft production shop -> /", "Services: architectural millwork, custom cabinetry, custom woodwork, trim, moldings, built-in cabinetry, finish carpentry -> /", "Customer types: General Contractors, Architects & Designers, Property Owners -> /", "Industries: commercial, residential, healthcare, hospitality, corporate -> /", "Project examples: Boston professional office, healthcare facility, corporate caf\u00e9, hotel pub, residential kitchens, corporate reception areas -> /", "2022 Boston Society of Architects Award -> /", "Charlie Trickett, General Mgr. -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "We have a 10,000 square foot production shop where we do all of our millwork and finishing.", "founded_year": "1975", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='trickett-woodworks-co' AND approved AND profile IS NUL