UPDATE companies SET description='TrueChoicePack was founded in 2013 in West Chester Township, Ohio. The company began as a total solutions provider for private label and customized disposable products, working with retailers, distributors, and food service partners from concept to delivery.

The company develops and supplies a broad portfolio of disposable products, including compostable cutlery, plates, bowls, food containers, trash can liners, and aluminum foil. Its in-house brands—Progress, BioGreenChoice, and EcoWay—cover everyday essentials, sustainable foodservice solutions, and tree-free paper products made from bamboo and sugarcane fiber. TrueChoicePack operates an agile manufacturing network that leverages multiple pre-qualified manufacturing partners across key regions, supported by global operations with offices in the United States and India and a network of warehouses and factories. The firm handles product development, global sourcing, quality management, warehousing, and distribution, working with materials such as bagasse, bamboo, birchwood, PLA, CPLA, PHA, polypropylene, polystyrene, polyethylene, and low-density polyethylene.

TrueChoicePack serves retail, foodservice, wholesale, commercial, and government customers, including Fortune 500 retailers. Its private label programs provide both eco-friendly and traditional product lines tailored to each client’s specifications.

The company differentiates itself through its agile manufacturing model, which enables rapid volume shifts and supply route reconfiguration, and through proactive compliance monitoring of evolving regulations across states and countries. It maintains certifications including BPI, FDA food-safe, ISO, UL, SGS, and BRC, and employs an in-house R&D team led by PhD biochemists and supply chain engineers.', certifications=ARRAY['BPI','FDA food-safe','ISO','UL','SGS','BRC']::text[], profile='{"capabilities": ["Private label brand development", "Customized disposable products", "Product development", "Global sourcing", "Warehousing", "Compostable cutlery", "Compostable plates & bowls", "Sustainable food containers", "Trash can liners", "Aluminum foil", "Material selection (biodegradable, eco-friendly, traditional paper and plastic)", "ERP system for supply chain management", "Global operations (offices in US and India)", "Customer service/account management", "Risk management (insurance throughout supply chain)", "Quality management and product quality certifications", "Compliance monitoring (product, material, food contact, sustainability)", "Certifications & standards navigation (BPI, FDA, ISO, UL, SGS, BRC)"], "industries": ["Retail", "Foodservice", "Wholesale", "Commercial", "Government"], "materials": ["Bagasse", "Bamboo", "Birchwood", "PLA", "CPLA", "PHA", "Polypropylene (PP)", "Polystyrene (PS)", "Polyethylene (PE)", "Low-density polyethylene (LDPE)", "Sugarcane fiber"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Agile manufacturing network with multiple pre-qualified partners enabling rapid volume shifts and route reconfiguration", "Global operations with offices in the U.S. and India and a worldwide warehouse and factory network", "In-house R&D team led by PhD biochemists and supply chain engineers", "Proactive compliance monitoring of state and national regulations", "Certifications including BPI, FDA food-safe, ISO, UL, SGS, and BRC"], "facts_used": ["Founded in 2013 -> db", "Headquarters in West Chester Township, Ohio -> db", "Private label brand development -> capabilities page", "Customized disposable products -> capabilities page", "Product development -> capabilities page", "Global sourcing -> capabilities page", "Warehousing -> capabilities page", "Compostable cutlery -> capabilities page", "Compostable plates & bowls -> capabilities page", "Sustainable food containers -> capabilities page", "Trash can liners -> capabilities page", "Aluminum foil -> capabilities page", "In-house brands: Progress, BioGreenChoice, EcoWay -> home page", "Agile manufacturing network with multiple pre-qualified manufacturing partners -> home page", "Global operations with offices in US and India -> capabilities page", "ERP system for supply chain traceability -> capabilities page", "In-house R&D team led by PhD biochemists and supply chain engineers -> capabilities page", "Risk management with insurance throughout supply chain -> capabilities page", "Quality management and certifications (BPI, FDA food-safe, ISO, UL, SGS, BRC) -> capabilities page", "Proactive compliance monitoring -> home page", "Materials: bagasse, bamboo, birchwood, PLA, CPLA, PHA, PP, PS, PE, LDPE -> home page", "Industries served: retail, foodservice, wholesale, commercial, government -> home page", "Fortune 500 retailers -> description", "Dynamic routing, risk and supplier intelligence -> home page", "Consistent delivery -> home page"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "We design and manufacture your esteemed private label brand products cost-effectively", "founded_year": "2013", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='truechoicepack' AND approved AND profile IS NULL;
UPDATE companies SET description='Tulsa Plastics Company was founded in 1941 in Tulsa, Oklahoma, initially producing plastic covers for household water coolers. Within months the family-owned business pivoted to manufacturing parts for the World War II effort, establishing a foundation in precision fabrication that continues today.

The company operates as a full-line plastics distributor and fabricator, offering waterjet cutting, CNC routing, milling, and lathe turning with live tooling, custom tape converting, CNC saw cut-to-size, diamond edge polishing, and heat bending. Its equipment includes CNC routers, waterjets, CNC panel saws, a diamond edge polisher, and a heat bender, enabling production of parts from plastics, composites, and metals for both prototype and production volumes.

Tulsa Plastics serves aerospace, chemical, oil and gas, food processing, retail, and convenience-store sectors, supplying materials such as acrylic, polycarbonate, Kydex, specialty tapes, masking films, window films, adhesives, and aerospace laminates. It is an authorized distributor for major manufacturers including Evonik, 3M, Covestro, and Kydex, and machines components for several Fortune 500 companies.', certifications=ARRAY['ISO 9001','AS9100']::text[], profile='{"capabilities": ["Waterjet cutting", "CNC routing", "CNC milling", "CNC lathe turning with live tooling", "Custom tape converting", "CNC saw cut-to-size", "Diamond edge polishing", "Heat bending", "Plastic materials distribution", "Custom fabrication of plastics, composites, and metals"], "industries": ["Aerospace", "Chemical", "Oil and gas", "Food processing", "Retail", "Convenience stores", "Military/Defense"], "materials": ["Acrylic", "Polycarbonate", "Kydex", "Specialty tapes", "Masking films", "Window films", "Adhesives", "Aerospace laminates", "Nylon (Zytel)", "Composites", "Metals"], "equipment": ["CNC routers", "Waterjets", "CNC panel saws", "Diamond edge polisher", "Heat bender"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Holds both AS9100 and ISO 9001 certifications", "Authorized distributor for leading plastics manufacturers", "In-house waterjet and CNC machining with tight tolerances", "Custom tape converting to precise widths", "Family-owned since 1941"], "facts_used": ["Founded in 1941 -> /about-us", "Family owned and operated -> /", "ISO9001 and AS9100 certified -> /, /about-us, /services", "Equipment: CNC routers, waterjets, CNC panel saws, diamond edge polisher, heat bender -> /about-us", "Industries served: aerospace, chemical, oil and gas, food processing, retail, convenience stores -> /about-us", "Services: waterjet cutting, CNC machining, custom tape converting, CNC saw cut-to-size, diamond edge polishing -> /services", "Materials: acrylic, polycarbonate, Kydex, specialty tapes, masking, window film, adhesives, aerospace laminates -> /", "Authorized distributor for top plastics manufacturers -> /about-us", "Quick turnaround times and competitive pricing -> /about-us", "Fortune 500 customers -> /about-us", "State-of-the-art plastics fabricator -> /about-us", "Garage shop roots in 1941 -> /about-us", "War effort parts during WWII -> /about-us", "CNC routing, milling, lathe turning with live tooling -> /services", "Custom fabrication -> /services", "AS9100 and ISO 9001 compliance -> /services", "Tight tolerance aerospace parts -> /services", "Plastic materials distribution -> /", "Brands carried: Evonik Acrylite, Plexiglas, Kydex, 3M, etc. -> /", "Suppliers: Arkema Plexiglas, Evonik Industries, 3M, Covestro Makrolon, Quadrant, Ensinger, PolyOne, Kydex, Kommerling -> /about-us"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "one of the top independent full-line plastics distribution and manufacturing companies in North America", "founded_year": "1941", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='tulsa-plastics-co' AND approved AND profile IS NULL;
UPDATE companies SET description='Tulsa Sheet Metal operates from Tulsa, Oklahoma, where it has been in business since 1949.

The shop provides custom metal fabrication with a range of CNC and manual processes: shearing, punching, burning, forming, bending, pressing, stamping, welding, repair, rolling, sawing, cutting, drilling, grinding, polishing, and painting, plus assembly and subassembly. An in-house engineer assists with custom designs. The facility is described as fully equipped for high-capacity orders using larger, heavier, and thicker materials, and works with aluminum, stainless steel, copper, brass, and alloy in sheet, plate, or structural shapes. Materials can be supplied by the shop or shipped directly by the customer.

